async function main({ params }) {
  const raw = (params.agentResult || '').trim();
  let scenes = [];

  // 优先尝试直接 JSON.parse
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) {
      scenes = parsed;
    } else if (parsed && Array.isArray(parsed.scenes)) {
      scenes = parsed.scenes;
    }
  } catch (e) {
    // 兜底：从字符串中截取第一个 [...] 段再尝试解析
    const match = raw.match(/\[[\s\S]*\]/);
    if (match) {
      try {
        scenes = JSON.parse(match[0]);
      } catch (e2) {
        scenes = [];
      }
    }
  }

  // 标准化：严格按照 { index, text, prompt } 三个字段输出，不做字段猜测
  const normalized = scenes.map((item, idx) => {
    if (typeof item === 'string') {
      return { index: idx + 1, text: '', prompt: item };
    }
    if (!item || typeof item !== 'object') {
      return { index: idx + 1, text: '', prompt: '' };
    }
    return {
      index: idx + 1,
      text: typeof item.text === 'string' ? item.text : '',
      prompt: typeof item.prompt === 'string' ? item.prompt : '',
    };
  });

  return {
    scenes: normalized,
    count: normalized.length,
  };
}

async function main({ params }) {
    const ret = {
      "tracks": [
        {
          "id": "1",
          "title": "背景音乐",
          "type": "audio"
        },
        {
          "id": "2",
          "title": "视频",
          "type": "video"
        },
        {
          "id": "3",
          "title": "配音",
          "type": "audio"
        },
        {
          "id": "4",
          "title": "字幕",
          "type": "text"
        }
      ],
      "items": []
    }
    const animations = ['缩放','向右缩放','向左缩放']
    let start = 0
    params.list.forEach(({duration, image, text, audio}, i) => {
      if(duration <= 0) duration = 1
      ret.items.push({
        "type": "image",
        "data": {
          "path": image[0],
          "track": "2",
          "start": start,
          "duration": duration,
          "animations": {
            "name": animations[i % animations.length],
            "duration": duration
          }
        }
      })
      ret.items.push({
        "type": "subtitle",
        "data": {
          "text": text,
          "track": "4",
          "start": start,
          "duration": duration
        }
      })

      ret.items.push({
        "type": "vocal",
        "data": {
          "path": audio,
          "track": "3",
          "start": start,
          "duration": duration
        }
      })

      start += duration * 1
    })
    if(params.bgm != '') ret.items.push({
      "type": "music",
      "data": {
        "track": "1",
        "path": params.bgm,
        "start": 0,
        "duration": start
      }
    })

    return ret
}

